// LSH hotel.checkin / hotel.checkout → decide which scene to run.
const b = $input.first().json.body || {};
const d = b.data || {};
const isIn = b.event === 'hotel.checkin';
const summary = isIn
  ? '🔑 Check-in room ' + d.room + (d.guest ? (' — ' + d.guest) : '') + (d.nights ? (', ' + d.nights + ' nights') : '') + '. Run arrival scene.'
  : '👋 Check-out room ' + d.room + '. Run departure scene.';
return [{ json: { event: b.event, action: isIn ? 'arrival' : 'departure', room: d.room, summary, data: d } }];
